import { defineConfig, type Plugin } from 'vite';
import { existsSync, readdirSync } from 'node:fs';
import { resolve } from 'node:path';
import { fillHome } from './src/markup.ts';

// Multi-page static site: the home plus one page per case in work/<slug>/,
// generated by scripts/build-cases.ts before dev and build.
const root = import.meta.dirname;

const workDir = resolve(root, 'work');
const cases = existsSync(workDir) ? readdirSync(workDir) : [];

/** The home's screens are built from src/content.ts, so the data lives in one place. */
const homeMarkup = (): Plugin => ({
  name: 'home-markup',
  transformIndexHtml: {
    order: 'pre',
    handler: (html, { path }) => (path === '/index.html' ? fillHome(html) : html),
  },
});

export default defineConfig({
  plugins: [homeMarkup()],
  build: {
    rollupOptions: {
      input: {
        home: resolve(root, 'index.html'),
        ...Object.fromEntries(cases.map((slug) => [slug, resolve(workDir, slug, 'index.html')])),
      },
    },
  },
});
